def evidence(start,end):
    spans=[]
    for cid,c in CH.items():
        a=max(start,c['start_line']);b=min(end,c['end_line'])
        if a<=b:spans.append({'chapter_id':cid,'start_line':a,'end_line':b})
    assert spans and sum(x['end_line']-x['start_line']+1 for x in spans)==end-start+1
    return spans

audit=json.loads((HERE/'thread-final-review.json').read_text(encoding='utf-8'))
assert set(decisions)=={x['key'] for x in audit['entries']}
for item in audit['entries']:
    status,note,ranges=decisions[item['key']]
    final=item['final'];final['status']=status;final['resolution_note']=note
    extra=[e for a,b in ranges for e in evidence(a,b)]
    final['evidence']=list({json.dumps(e,sort_keys=True):e for e in final['evidence']+extra}.values())
    item['reviewed_at_book_end']=True
audit['complete_as_of_volume']=18
(HERE/'thread-final-review.json').write_text(json_text(audit),encoding='utf-8')
print(json.dumps({'individually_reviewed_threads':len(decisions)}))
